insert into passages (id, text, difficulty_level, b, active) values
('91d1436d-414d-4dc6-8a83-dc7f2e16d204', 'The phenomenon of groupthink, first described by psychologist Irving Janis in the early 1970s, refers to the tendency of cohesive groups to prioritize consensus and harmony over a realistic appraisal of alternative courses of action. Janis identified this pattern while studying several major American foreign policy failures, most notably the Bay of Pigs invasion, and concluded that the very cohesiveness that made these decision-making groups effective in other respects also made them susceptible to a kind of collective self-deception. Members of a group experiencing groupthink often suppress their own doubts rather than voice dissent, out of a desire to maintain group unity or avoid being perceived as disloyal. This dynamic is frequently reinforced by what Janis termed "self-appointed mindguards," individuals within the group who actively discourage the introduction of information that might disrupt the emerging consensus. Organizational psychologists have since proposed several countermeasures, including designating a formal "devil''s advocate" whose explicit role is to challenge prevailing opinions, encouraging leaders to withhold their own preferences until subordinates have spoken, and seeking outside opinions from experts who are not part of the group''s usual decision-making circle. Critics of the concept, however, argue that groupthink has been invoked so broadly in both academic literature and popular discourse that it risks becoming a catch-all explanation for any poor group decision, regardless of whether the specific psychological mechanisms Janis described were actually at play.', 4, 1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('69ab44f0-888e-4e4e-951d-a5ef525c329e', 'sentence_completion', 'The senator''s response to the scandal was widely seen as an attempt to ___ responsibility rather than confront it directly.', NULL, '[{"id": "d", "text": "deflect"}, {"id": "c", "text": "embrace"}, {"id": "b", "text": "accept"}, {"id": "a", "text": "acknowledge"}]'::jsonb, 0, '{"strategy": "rather than confront it directly = במקום להתמודד ישירות. איזו תגובה מנוגדת להתמודדות ישירה?", "correct_reason": "deflect = להסיט. הסטת אחריות היא הפוך מהתמודדות ישירה.", "options_analysis": ["נכון! deflect = להסיט — מתאים לניסיון להימנע מעימות ישיר", "embrace = לאמץ — הפוך מהניסיון להימנע", "accept = לקבל — הפוך מהניסיון להימנע מהתמודדות", "acknowledge = להכיר ב- — הפוך מהניסיון להתחמק"]}', 1.28, 1.0, 0.25, 4, 'ai', NULL, true),
('5c8a0a87-4005-474e-91b2-bb49847ba982', 'sentence_completion', 'The author''s prose style is often ___ , packing complex ideas into remarkably few words.', NULL, '[{"id": "a", "text": "verbose"}, {"id": "d", "text": "terse"}, {"id": "b", "text": "elaborate"}, {"id": "c", "text": "redundant"}]'::jsonb, 1, '{"strategy": "packing complex ideas into remarkably few words = דוחס רעיונות מורכבים למעט מילים. איזה סגנון עושה זאת?", "correct_reason": "terse = תמציתי. סגנון תמציתי דוחס רעיונות למעט מילים.", "options_analysis": ["verbose = מלל רב — הפוך מ''few words''", "נכון! terse = תמציתי — מתאים ל''remarkably few words''", "elaborate = מפורט/מסועף — הפוך מ''few words''", "redundant = חוזר על עצמו — הפוך מתמציתיות"]}', 1.9, 1.0, 0.25, 4, 'ai', NULL, true),
('9bd3617a-9e12-4353-9e25-7f354ca8da52', 'sentence_completion', 'Critics praised the film for its ___ portrayal of a difficult subject, avoiding both sentimentality and cynicism.', NULL, '[{"id": "c", "text": "crude"}, {"id": "d", "text": "simplistic"}, {"id": "a", "text": "nuanced"}, {"id": "b", "text": "one-dimensional"}]'::jsonb, 2, '{"strategy": "avoiding both sentimentality and cynicism = נמנע גם מרגשנות וגם מציניות. איזה תיאור משיג איזון כזה?", "correct_reason": "nuanced = מדוקדק/רב-גוני. תיאור מאוזן שנמנע מקיצוניות משני הכיוונים הוא ניואנסי.", "options_analysis": ["crude = גס/לא מעודן — הפוך מתיאור מדוקדק", "simplistic = פשטני — הפוך מתיאור מאוזן ומורכב", "נכון! nuanced = רב-גוני/מדוקדק — מתאים לאיזון בין שני קצוות", "one-dimensional = חד-ממדי — הפוך מתיאור מאוזן"]}', 1.33, 1.0, 0.25, 4, 'ai', NULL, true),
('59923703-f127-4664-a722-006302c55a9b', 'sentence_completion', 'Despite the company''s public assurances, internal documents reveal a far more ___ financial situation.', NULL, '[{"id": "b", "text": "stable"}, {"id": "c", "text": "robust"}, {"id": "a", "text": "secure"}, {"id": "d", "text": "precarious"}]'::jsonb, 3, '{"strategy": "despite public assurances...far more = למרות הבטחות פומביות...הרבה יותר. ניגוד בין תדמית למציאות.", "correct_reason": "precarious = רעוע/מסוכן. מסמכים פנימיים שסותרים הבטחות ציבוריות מרמזים על מצב לא יציב.", "options_analysis": ["stable = יציב — הפוך מהניגוד ל''public assurances''", "robust = איתן — הפוך מהניגוד לתדמית ציבורית", "secure = בטוח — הפוך מהניגוד לתדמית ציבורית", "נכון! precarious = רעוע — מתאים לניגוד בין הבטחות למציאות פנימית"]}', 1.41, 1.0, 0.25, 4, 'ai', NULL, true),
('4d76ce7d-f3f7-4f3b-9410-716bd8ea74b3', 'sentence_completion', 'The negotiator''s ability to remain ___ under pressure was crucial to reaching a peaceful resolution.', NULL, '[{"id": "a", "text": "composed"}, {"id": "b", "text": "erratic"}, {"id": "d", "text": "flustered"}, {"id": "c", "text": "agitated"}]'::jsonb, 0, '{"strategy": "crucial to reaching a peaceful resolution = חיוני להגעה לפתרון שליו. איזו תכונה תחת לחץ עוזרת להגיע לפתרון שליו?", "correct_reason": "composed = מיושב/רגוע. שמירה על קור רוח תחת לחץ עוזרת להגיע לפתרון.", "options_analysis": ["נכון! composed = רגוע — מתאים לתכונה שמובילה לפתרון שליו", "erratic = לא יציב — הפוך מתכונה מועילה למו''מ", "flustered = נבוך/מבולבל — הפוך מתכונה שעוזרת לפתרון שליו", "agitated = נסער — הפוך מתכונה מועילה תחת לחץ"]}', 1.46, 1.0, 0.25, 4, 'ai', NULL, true),
('040c86a3-1036-4779-9aac-1db30d9dd737', 'sentence_completion', 'The committee''s findings were ___ by subsequent investigations, which uncovered even more troubling evidence.', NULL, '[{"id": "a", "text": "ignored"}, {"id": "d", "text": "corroborated"}, {"id": "b", "text": "refuted"}, {"id": "c", "text": "dismissed"}]'::jsonb, 1, '{"strategy": "uncovered even more troubling evidence = חשפו ראיות מטרידות נוספות. מה עשו חקירות שמצאו ראיות נוספות תומכות?", "correct_reason": "corroborated = אישרו/חיזקו. חקירות שמצאו עוד ראיות תומכות מחזקות את הממצאים.", "options_analysis": ["ignored = התעלמו — סותר את קיום החקירה שמצאה ראיות", "נכון! corroborated = חיזקו — מתאים לחקירות שמצאו ראיות נוספות תומכות", "refuted = הפריכו — הפוך מ''uncovered even more troubling evidence'' שתומך בממצאים", "dismissed = דחו — הפוך מחיזוק הממצאים"]}', 1.15, 1.0, 0.25, 4, 'ai', NULL, true),
('bf4adbac-2e95-4b45-9cc1-76f8e383d9d7', 'sentence_completion', 'The politician''s speech was carefully crafted to ___ controversy while still addressing the core issue.', NULL, '[{"id": "b", "text": "provoke"}, {"id": "a", "text": "court"}, {"id": "c", "text": "sidestep"}, {"id": "d", "text": "incite"}]'::jsonb, 2, '{"strategy": "while still addressing the core issue = תוך התייחסות לנושא המרכזי. איך מנסחים נאום שנמנע ממחלוקת אך עדיין נוגע בנושא?", "correct_reason": "sidestep = לעקוף/להתחמק. נאום מנוסח בזהירות מנסה לעקוף מחלוקת.", "options_analysis": ["provoke = לעורר — הפוך מניסיון להימנע ממחלוקת", "court = לחזר אחרי/לבקש — הפוך מניסיון להימנע", "נכון! sidestep = לעקוף — מתאים לניסיון להימנע ממחלוקת תוך התייחסות לנושא", "incite = להסית — הפוך מניסיון להימנע ממחלוקת"]}', 1.26, 1.0, 0.25, 4, 'ai', NULL, true),
('4a9be8e6-08e5-45de-a3d5-37ee08eaed3c', 'sentence_completion', 'The economist''s ___ predictions about the market crash proved remarkably accurate in hindsight.', NULL, '[{"id": "d", "text": "misguided"}, {"id": "b", "text": "careless"}, {"id": "c", "text": "dismissed"}, {"id": "a", "text": "prescient"}]'::jsonb, 3, '{"strategy": "proved remarkably accurate in hindsight = התבררו כמדויקות במבט לאחור. איזו תחזית מתבררת כמדויקת?", "correct_reason": "prescient = חזוני/צופה פני עתיד. תחזית שמתבררת כמדויקת מראש היא חזונית.", "options_analysis": ["misguided = מוטעה — הפוך מ''proved remarkably accurate''", "careless = חסרת זהירות — הפוך מתחזית מדויקת", "dismissed = שנדחתה — לא מתאר את איכות התחזית עצמה כמדויקת מראש", "נכון! prescient = חזוני — מתאים לתחזית שהתבררה כמדויקת מראש"]}', 1.82, 1.0, 0.25, 4, 'ai', NULL, true),
('ae1f307c-b1b0-4803-adb5-9389d7fa47cb', 'sentence_completion', 'The museum''s latest acquisition, though ___ by some art historians, has drawn large crowds.', NULL, '[{"id": "c", "text": "disputed"}, {"id": "b", "text": "endorsed"}, {"id": "d", "text": "celebrated"}, {"id": "a", "text": "praised"}]'::jsonb, 0, '{"strategy": "though...has drawn large crowds = למרות...משך קהל רב. ניגוד.", "correct_reason": "disputed = שנוי במחלוקת. יצירה שנויה במחלוקת עדיין יכולה למשוך קהל.", "options_analysis": ["נכון! disputed = שנוי במחלוקת — יוצר ניגוד הגיוני עם משיכת קהל", "endorsed = אושרה — לא יוצר ניגוד עם משיכת קהל", "celebrated = נחגגה — לא יוצר ניגוד עם ''has drawn large crowds''", "praised = שובחה — לא יוצר ניגוד עם משיכת קהל"]}', 1.61, 1.0, 0.25, 4, 'ai', NULL, true),
('89b9b2ec-fb7a-4697-bc05-183fd47801d6', 'sentence_completion', 'The report''s conclusions were based on ___ evidence, making its recommendations difficult to justify.', NULL, '[{"id": "c", "text": "substantial"}, {"id": "b", "text": "flimsy"}, {"id": "a", "text": "conclusive"}, {"id": "d", "text": "overwhelming"}]'::jsonb, 1, '{"strategy": "making its recommendations difficult to justify = מקשה להצדיק את ההמלצות. אילו ראיות מקשות על הצדקת מסקנות?", "correct_reason": "flimsy = רעועות/חלשות. ראיות חלשות מקשות להצדיק מסקנות.", "options_analysis": ["substantial = משמעותיות — הפוך מ''difficult to justify''", "נכון! flimsy = רעועות — מתאים לקושי בהצדקת המלצות", "conclusive = חד-משמעיות — הפוך מ''difficult to justify''", "overwhelming = מכריעות — הפוך מ''difficult to justify''"]}', 1.34, 1.0, 0.25, 4, 'ai', NULL, true),
('69fc40bd-d244-43bf-a9ad-627cb446d5c5', 'sentence_completion', 'The CEO''s decision to ___ the failing division rather than invest further resulted in significant cost savings.', NULL, '[{"id": "a", "text": "expand"}, {"id": "c", "text": "strengthen"}, {"id": "b", "text": "divest"}, {"id": "d", "text": "fund"}]'::jsonb, 2, '{"strategy": "rather than invest further = במקום להשקיע יותר. מה עושים למחלקה כושלת במקום להשקיע בה?", "correct_reason": "divest = למכור/להיפטר מ-. מחלקה כושלת שלא משקיעים בה נמכרת בדרך כלל.", "options_analysis": ["expand = להרחיב — הפוך מ''rather than invest further''", "strengthen = לחזק — סותר ''rather than invest further''", "נכון! divest = להיפטר מ- — מתאים לחלופה להשקעה נוספת", "fund = לממן — סותר ''rather than invest further''"]}', 1.44, 1.0, 0.25, 4, 'ai', NULL, true),
('0beaaa04-dafc-4838-89c0-60813e30e2f4', 'sentence_completion', 'The professor''s argument, while intellectually rigorous, struck many students as excessively ___ and disconnected from real-world concerns.', NULL, '[{"id": "d", "text": "concrete"}, {"id": "b", "text": "practical"}, {"id": "c", "text": "applicable"}, {"id": "a", "text": "abstract"}]'::jsonb, 3, '{"strategy": "disconnected from real-world concerns = מנותק מדאגות העולם האמיתי. איזו תכונה מרמזת על ניתוק מהמציאות?", "correct_reason": "abstract = מופשט. טיעון מנותק מהמציאות נחשב מופשט מדי.", "options_analysis": ["concrete = קונקרטי — הפוך מ''disconnected from real-world''", "practical = מעשי — הפוך מ''disconnected from real-world concerns''", "applicable = ישים — הפוך מ''disconnected from real-world concerns''", "נכון! abstract = מופשט — מתאים לניתוק מהמציאות"]}', 1.38, 1.0, 0.25, 4, 'ai', NULL, true),
('bb535b8f-cc9a-4738-983e-a51ff8f4b926', 'restatement', 'The novel''s protagonist, despite her flaws, ultimately emerges as a sympathetic and relatable figure.', NULL, '[{"id": "d", "text": "Although the protagonist has flaws, readers ultimately come to find her sympathetic and relatable."}, {"id": "b", "text": "The protagonist is portrayed as entirely unlikable by the end of the novel."}, {"id": "c", "text": "The protagonist has no flaws whatsoever throughout the novel."}, {"id": "a", "text": "The novel never develops its protagonist as a character."}]'::jsonb, 0, '{"strategy": "despite flaws, ultimately sympathetic = למרות פגמים, בסוף אהודה. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: למרות פגמים, מתגלה כאהודה", "הפוך — סותר ''sympathetic and relatable''", "סותר ''despite her flaws'' — יש לה פגמים", "סותר את קיום ההתפתחות המתוארת"]}', 1.65, 1.0, 0.25, 4, 'ai', NULL, true),
('95c7014f-cf1f-496b-b249-e5bf2fe5422b', 'restatement', 'The company''s expansion into overseas markets, though initially risky, ultimately proved to be a lucrative decision.', NULL, '[{"id": "a", "text": "The company decided against expanding into overseas markets."}, {"id": "b", "text": "Although risky at first, the company''s move into overseas markets eventually turned out to be profitable."}, {"id": "d", "text": "The company''s expansion into overseas markets was a financial failure."}, {"id": "c", "text": "The company''s overseas expansion was safe from the very beginning."}]'::jsonb, 1, '{"strategy": "though initially risky, ultimately lucrative = למרות סיכון בהתחלה, בסוף רווחי. ניגוד.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום ההתרחבות המתוארת", "נכון! אותה משמעות מדויקת: מסוכן בהתחלה, בסוף רווחי", "הפוך — ''financial failure'' סותר ''lucrative decision''", "הפוך — סותר ''initially risky''"]}', 1.6, 1.0, 0.25, 4, 'ai', NULL, true),
('6d2ebfb0-3b08-4fef-9993-5ea1fb1f1652', 'restatement', 'The senator''s remarks, widely condemned by opponents, were nonetheless defended by her supporters as courageous.', NULL, '[{"id": "b", "text": "The senator''s supporters also condemned her remarks."}, {"id": "a", "text": "No one had any reaction to the senator''s remarks."}, {"id": "d", "text": "While opponents strongly criticized the senator''s remarks, her supporters viewed them as brave."}, {"id": "c", "text": "Both opponents and supporters condemned the senator''s remarks equally."}]'::jsonb, 2, '{"strategy": "widely condemned by opponents, defended by supporters = ניגוד בין קבוצות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — התומכים דווקא הגנו, לא גינו", "סותר את קיום התגובות המתוארות", "נכון! אותה משמעות מדויקת: מתנגדים ביקרו, תומכים ראו כאמיצים", "סותר את ההבדל המפורש בין מתנגדים לתומכים"]}', 1.42, 1.0, 0.25, 4, 'ai', NULL, true),
('d20c16e1-a826-4a6d-8584-b3f19cb8b6f4', 'restatement', 'The restaurant''s reputation, tarnished by a series of negative reviews, has since been restored through consistent quality.', NULL, '[{"id": "b", "text": "The restaurant''s reputation remains damaged despite its efforts."}, {"id": "c", "text": "The restaurant''s reputation was never affected by any negative reviews."}, {"id": "d", "text": "The restaurant closed down due to negative reviews."}, {"id": "a", "text": "After being damaged by negative reviews, the restaurant rebuilt its reputation by maintaining consistent quality."}]'::jsonb, 3, '{"strategy": "tarnished...restored = נפגם...שוקם. ניגוד עבר-הווה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''has since been restored''", "הפוך — סותר ''tarnished by a series of negative reviews''", "סותר ''has since been restored'' — המסעדה עדיין קיימת ומשוקמת", "נכון! אותה משמעות מדויקת: נפגם ואז שוקם באמצעות איכות עקבית"]}', 1.31, 1.0, 0.25, 4, 'ai', NULL, true),
('f80cd90a-4db1-4744-8835-5cb4069d9142', 'restatement', 'The proposal, though praised for its ambition, was ultimately rejected due to its impractical implementation timeline.', NULL, '[{"id": "c", "text": "Despite being admired for its ambitious scope, the proposal was turned down because its timeline was unrealistic."}, {"id": "b", "text": "The proposal was approved because of its realistic timeline."}, {"id": "d", "text": "The proposal was rejected because it lacked ambition."}, {"id": "a", "text": "No one had any opinion about the proposal''s ambition."}]'::jsonb, 0, '{"strategy": "though praised for ambition, rejected due to timeline = ניגוד בין תכונה חיובית לדחייה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: הוערך על שאפתנות, נדחה בגלל לו''ז לא מציאותי", "הפוך — ''approved'' סותר ''rejected''", "הפוך — סותר ''praised for its ambition''", "סותר ''praised for its ambition''"]}', 1.4, 1.0, 0.25, 4, 'ai', NULL, true),
('4fd4dbcb-dbfe-4755-bdf7-dc658856a920', 'restatement', 'The startup''s founder, initially dismissed as naive by industry veterans, later earned their grudging respect.', NULL, '[{"id": "d", "text": "The founder never gained any respect from industry veterans."}, {"id": "b", "text": "Although industry veterans first considered the founder naive, they eventually came to respect him, if reluctantly."}, {"id": "c", "text": "The founder was never criticized by anyone in the industry."}, {"id": "a", "text": "Industry veterans always respected the founder from the very beginning."}]'::jsonb, 1, '{"strategy": "initially dismissed, later earned respect = ניגוד בין תחילה לסוף.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''later earned their grudging respect''", "נכון! אותה משמעות מדויקת: תחילה נחשב נאיבי, בסוף זכה בכבוד מסויג", "סותר ''initially dismissed as naive by industry veterans''", "הפוך — סותר ''initially dismissed as naive''"]}', 1.73, 1.0, 0.25, 4, 'ai', NULL, true),
('e2fc3403-e6eb-4952-a8bb-e92dfc2f93ea', 'restatement', 'The film''s visual effects, though groundbreaking for their time, appear dated by today''s standards.', NULL, '[{"id": "c", "text": "The film had no visual effects at all."}, {"id": "b", "text": "The film''s visual effects still look modern and impressive today."}, {"id": "d", "text": "Although the visual effects were innovative when the film was made, they now look outdated."}, {"id": "a", "text": "The visual effects were considered unimpressive even when the film was first released."}]'::jsonb, 2, '{"strategy": "though groundbreaking then, dated now = ניגוד בין אז להיום.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום האפקטים הוויזואליים", "הפוך — סותר ''appear dated by today''s standards''", "נכון! אותה משמעות מדויקת: חדשניים בזמנם, נראים מיושנים היום", "הפוך — סותר ''groundbreaking for their time''"]}', 1.42, 1.0, 0.25, 4, 'ai', NULL, true),
('f640c392-a765-4189-b9d8-65bf28325b39', 'restatement', 'The city''s aging water infrastructure, neglected for decades, finally received significant investment this year.', NULL, '[{"id": "b", "text": "The city has no water infrastructure to speak of."}, {"id": "c", "text": "The city''s water infrastructure will never be repaired."}, {"id": "a", "text": "The water infrastructure has received consistent investment for decades."}, {"id": "d", "text": "After decades of neglect, the city''s water infrastructure finally got substantial funding this year."}]'::jsonb, 3, '{"strategy": "neglected for decades, finally received investment = ניגוד בין הזנחה להשקעה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום התשתית המתוארת", "הפוך — סותר ''finally received significant investment''", "הפוך — סותר ''neglected for decades''", "נכון! אותה משמעות מדויקת: אחרי הזנחה ארוכה, קיבל השקעה משמעותית השנה"]}', 1.81, 1.0, 0.25, 4, 'ai', NULL, true),
('d75a4403-e41c-4f6b-8425-5062019e682b', 'restatement', 'The witness''s account, corroborated by video evidence, left little doubt about what had actually occurred.', NULL, '[{"id": "c", "text": "Since video evidence supported the witness''s account, there was hardly any uncertainty about what happened."}, {"id": "a", "text": "The witness refused to give any account of the events."}, {"id": "d", "text": "There was no video evidence available in the case."}, {"id": "b", "text": "The witness''s account was contradicted by the video evidence."}]'::jsonb, 0, '{"strategy": "corroborated by evidence, left little doubt = תמיכה מובילה לוודאות.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: הראיות תמכו, כמעט ואין אי-ודאות", "סותר את קיום העדות המתוארת", "סותר ''corroborated by video evidence''", "הפוך — סותר ''corroborated by video evidence''"]}', 1.64, 1.0, 0.25, 4, 'ai', NULL, true),
('9dbb991a-cbeb-4f9d-8bcc-e5394ddd8897', 'restatement', 'The company''s aggressive expansion strategy, while boosting short-term revenue, left it vulnerable to long-term financial instability.', NULL, '[{"id": "d", "text": "The expansion strategy hurt both short-term and long-term financial health."}, {"id": "b", "text": "Although the expansion increased revenue in the short term, it made the company susceptible to instability later on."}, {"id": "c", "text": "The company''s finances became more stable due to the expansion."}, {"id": "a", "text": "The expansion strategy had no effect on the company''s finances."}]'::jsonb, 1, '{"strategy": "boosting short-term, vulnerable long-term = ניגוד זמן קצר-ארוך.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''boosting short-term revenue''", "נכון! אותה משמעות מדויקת: הגדילה הכנסות בטווח קצר, אך חשפה לחוסר יציבות בטווח ארוך", "הפוך — סותר ''vulnerable to long-term financial instability''", "סותר את קיום ההשפעה הכספית המתוארת"]}', 1.25, 1.0, 0.25, 4, 'ai', NULL, true),
('9ebe764e-289a-4651-8b15-4349fe909efb', 'restatement', 'The playwright''s early works, largely overlooked by critics at the time, are now regarded as pioneering contributions to the genre.', NULL, '[{"id": "c", "text": "Critics immediately recognized the playwright''s early works as pioneering."}, {"id": "d", "text": "The playwright''s early works are still considered unimportant today."}, {"id": "b", "text": "Though critics mostly ignored the playwright''s early works back then, they are now seen as groundbreaking."}, {"id": "a", "text": "The playwright never wrote any early works."}]'::jsonb, 2, '{"strategy": "overlooked then, pioneering now = ניגוד בין אז להיום.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''largely overlooked by critics at the time''", "הפוך — סותר ''now regarded as pioneering contributions''", "נכון! אותה משמעות מדויקת: הוזנחו אז, נחשבים פורצי דרך היום", "סותר ''early works'' — כן נכתבו יצירות מוקדמות"]}', 1.28, 1.0, 0.25, 4, 'ai', NULL, true),
('3dd3f9b9-2ce1-452a-8c13-0311459d1bac', 'restatement', 'The negotiations, though fraught with tension, ultimately resulted in an agreement that satisfied both parties.', NULL, '[{"id": "c", "text": "The negotiations were relaxed and free of tension throughout."}, {"id": "b", "text": "The negotiations ended without any agreement being reached."}, {"id": "d", "text": "Only one side was satisfied with the final agreement."}, {"id": "a", "text": "Despite being tense, the negotiations eventually led to a deal that both sides found acceptable."}]'::jsonb, 3, '{"strategy": "though fraught with tension, ultimately satisfied both = ניגוד בין מתח לתוצאה חיובית.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''fraught with tension''", "הפוך — סותר ''resulted in an agreement''", "סותר ''satisfied both parties''", "נכון! אותה משמעות מדויקת: מתוחים, אך בסוף הובילו להסכם שמשביע רצון את שני הצדדים"]}', 1.25, 1.0, 0.25, 4, 'ai', NULL, true),
('a0f06db7-4014-47a7-b4e0-fa86b3aa57a2', 'reading_comprehension', 'What is the main purpose of the passage?', '91d1436d-414d-4dc6-8a83-dc7f2e16d204', '[{"id": "c", "text": "To describe the concept of groupthink, its origins, and the debate surrounding its use"}, {"id": "b", "text": "To provide a biography of psychologist Irving Janis"}, {"id": "a", "text": "To promote a specific business strategy for corporate leaders"}, {"id": "d", "text": "To argue that all group decisions are inherently flawed"}]'::jsonb, 0, '{"strategy": "שאלת מטרה/רעיון מרכזי — הפסקה מסבירה את מושג ה''חשיבה קבוצתית'' ומקורותיו והוויכוח סביבו.", "correct_reason": "הפסקה סוקרת הגדרה, מקור, מנגנון, פתרונות מוצעים וביקורת — דיון מקיף.", "options_analysis": ["נכון! תיאור המושג, מקורו והוויכוח סביבו = המטרה המרכזית", "לא מוזכר בפסקה כלל — הפסקה עוסקת ברעיון, לא בביוגרפיה", "לא מוזכר בפסקה כלל", "קיצוני מדי — הפסקה לא טוענת שכל החלטה קבוצתית פגומה"]}', 1.45, 1.0, 0.25, 4, 'ai', NULL, true),
('d63ac356-d4e1-4474-8258-53c8e1aa4bf1', 'reading_comprehension', 'According to the passage, what did Janis conclude about group cohesiveness?', '91d1436d-414d-4dc6-8a83-dc7f2e16d204', '[{"id": "a", "text": "That cohesiveness has no effect on group decision-making at all"}, {"id": "c", "text": "That the very cohesiveness that made groups effective also made them susceptible to collective self-deception"}, {"id": "b", "text": "That it always leads to better decision-making"}, {"id": "d", "text": "That cohesive groups never make foreign policy decisions"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את מסקנת יאניס על לכידות קבוצתית.", "correct_reason": "הפסקה אומרת: ''the very cohesiveness that made these decision-making groups effective in other respects also made them susceptible to a kind of collective self-deception''.", "options_analysis": ["סותר את כל הדיון בפסקה על השפעת לכידות", "נכון! נאמר במפורש בפסקה", "הפוך — הפסקה מתארת גם השפעה שלילית, לא רק חיובית", "סותר את הדוגמה על פלישת מפרץ החזירים"]}', 1.78, 1.0, 0.25, 4, 'ai', NULL, true),
('9cfd8400-1e1e-4885-b19d-561637d4dc3a', 'reading_comprehension', 'The word "suppress" in the passage most closely means:', '91d1436d-414d-4dc6-8a83-dc7f2e16d204', '[{"id": "a", "text": "to celebrate"}, {"id": "d", "text": "to express openly"}, {"id": "b", "text": "to hold back or restrain"}, {"id": "c", "text": "to encourage"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''suppress their own doubts rather than voice dissent''.", "correct_reason": "suppress = לדכא/להדחיק.", "options_analysis": ["לא קשור למשמעות המילה", "הפוך גמור למשמעות המילה", "נכון! suppress = לדכא/להדחיק", "הפוך גמור למשמעות המילה"]}', 1.43, 1.0, 0.25, 4, 'ai', NULL, true),
('9dc32e63-7ffd-4cbd-b16d-b93a9ad565e6', 'reading_comprehension', 'According to the passage, what is the role of a "self-appointed mindguard"?', '91d1436d-414d-4dc6-8a83-dc7f2e16d204', '[{"id": "a", "text": "To encourage all group members to voice their doubts"}, {"id": "d", "text": "To seek outside expert opinions for the group"}, {"id": "c", "text": "To formally challenge the group''s prevailing opinions"}, {"id": "b", "text": "To actively discourage information that might disrupt the group''s emerging consensus"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את תפקיד ה''מגן המחשבתי'' בפסקה.", "correct_reason": "הפסקה אומרת: ''individuals within the group who actively discourage the introduction of information that might disrupt the emerging consensus''.", "options_analysis": ["הפוך גמור מתפקיד ה-mindguard כפי שתואר בפסקה", "זהו אחד מהפתרונות המוצעים, לא תפקיד ה-mindguard", "זה תפקידו של ''devil''s advocate'' הפורמלי, לא של mindguard", "נכון! נאמר במפורש בפסקה"]}', 1.43, 1.0, 0.25, 4, 'ai', NULL, true),
('323b7b69-3a31-4e76-a0cf-c53bbcc089d3', 'reading_comprehension', 'What criticism of the groupthink concept is mentioned in the passage?', '91d1436d-414d-4dc6-8a83-dc7f2e16d204', '[{"id": "c", "text": "That it is invoked so broadly that it risks becoming a catch-all explanation regardless of whether the specific mechanisms were present"}, {"id": "a", "text": "That it only applies to business decisions, never to government decisions"}, {"id": "d", "text": "That Janis never provided any evidence for the concept"}, {"id": "b", "text": "That it has never been studied by any psychologist"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הביקורת בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''groupthink has been invoked so broadly...that it risks becoming a catch-all explanation for any poor group decision, regardless of whether the specific psychological mechanisms Janis described were actually at play''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה — הדוגמה שניתנה היא דווקא ממשלתית (מפרץ החזירים)", "סותר את קיום המחקר וההגדרה המפורטת שתוארה", "סותר את כל הפסקה שמתארת את המחקר של יאניס"]}', 1.34, 1.0, 0.25, 4, 'ai', NULL, true);